import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from collections import defaultdict

MAX_DRIVERS = 2

def design(feats):
    # Calculate effect sizes and p-values for all features
    effect_sizes = []
    for i, fid in enumerate(feats.ids):
        x = feats.x[:, i]
        y = feats.y
        mean_y1 = np.mean(x[y == 1])
        mean_y0 = np.mean(x[y == 0])
        effect_size = mean_y1 - mean_y0
        t_stat, p_val = stats.ttest_ind(x[y == 1], x[y == 0], equal_var=False)
        effect_sizes.append((fid, effect_size, p_val, t_stat))

    # Sort by absolute effect size
    effect_sizes.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates (correlated features)
    correlated_pairs = set()
    for line in """
PSQR10L~CDYF12B r=-0.93; PSQR10L~TEEO17 r=-0.91; OUB15P~AHA2 r=+0.91; 
TUES13~PSQR10L r=-0.90; NPR17~TEEO17 r=+0.90; CDYF12B~TEEO17 r=+0.86; 
JRBQ19P~PSQR10L r=-0.85; TUES13~CDYF12B r=+0.83; WXLS6~IVQS9 r=+0.82; 
PBAE5~PSQR10L r=+0.81; TUES13~FVOE11 r=+0.81; JRBQ19P~CDYF12B r=+0.81; 
TUES13~TEEO17 r=+0.80; EMM14~TEEO17 r=+0.80; REP5~PSQR10L r=+0.80; 
JRBQ19P~TEEO17 r=+0.80; PSQR10L~NPR17 r=-0.79; IBL2L~PSQR10L r=+0.78; 
PSQR10L~BVKH10 r=+0.78; PSQR10L~FVOE11 r=-0.77""".strip().split(';'):
        if line.strip():
            pair, _ = line.split(' r=')
            f1, f2 = pair.split('~')
            correlated_pairs.add((f1, f2))
            correlated_pairs.add((f2, f1))

    # Select non-correlated features
    selected_features = []
    for fid, eff, pval, tstat in effect_sizes:
        is_correlated = any((fid, other) in correlated_pairs or (other, fid) in correlated_pairs 
                           for other in selected_features)
        if not is_correlated:
            selected_features.append(fid)
            if len(selected_features) >= MAX_DRIVERS:
                break

    # If no strong effects, return empty design
    if not selected_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # For the top features, check if interactions improve model
    drivers = tuple(selected_features[:MAX_DRIVERS])

    # Build regression components
    columns = selected_features[:MAX_DRIVERS]
    products = []
    loadings = {fid: 1.0 for fid in columns}

    # Check for interaction terms between top features
    for i, fid1 in enumerate(columns):
        for j, fid2 in enumerate(columns[i+1:], i+1):
            # Check if interaction term would be beneficial
            # Simple heuristic: if both have large effect sizes, consider interaction
            if abs(effect_sizes[feats.column(fid1)][1]) > 0.2 and abs(effect_sizes[feats.column(fid2)][1]) > 0.2:
                products.append((fid1, fid2))

    return Design(drivers=drivers, columns=tuple(columns), products=tuple(products), loadings=loadings)

